// ---------------------------------------------------------------
// app.js – Secure, validated, and robust Express server
// ---------------------------------------------------------------

require('dotenv').config();               // Load .env (optional)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, param, query, validationResult } = require('express-validator');

const app = express();

// --------------------------
// 1. Middleware stack (security & logging)
// --------------------------
app.use(helmet());                           // Security headers
app.use(
  cors({
    // Example: allow only origins listed in CORS_ORIGIN env var
    origin: process.env.CORS_ORIGIN?.split(',') || '*',
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
  })
);
app.use(express.json());                    // Parse JSON bodies
app.use(express.urlencoded({ extended: true }));
app.use(morgan('combined'));                // Structured request logs

// --------------------------
// 2. Rate limiting (basic public API protection)
// --------------------------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/health', apiLimiter);   // optional – health checks usually stay open
app.use('/users', apiLimiter);

// --------------------------
// 3. Helper to wrap async route handlers
// --------------------------
const asyncWrapper = fn => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// --------------------------
// 4. Input validation utilities
// --------------------------
const validate = validations => async (req, res, next) => {
  await Promise.all(validations.map(v => v.run(req)));
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Return a 400 with a sanitized error payload – never echo raw user input
    return res.status(400).json({ error: 'Invalid request', details: errors.array() });
  }
  next();
};

