  '/users',
  validate([
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt()
      .withMessage('limit must be an integer between 1 and 100'),
  ]),
  asyncWrapper(async (req, res) => {
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const limit = req.query.limit;
    const payload = limit ? allUsers.slice(0, limit) : allUsers;

    // In a real API you would also sanitise any user‑generated fields before sending.
    res.json(payload);
  })
);

// ---------------------------------------------------------------
// 6. Central error‑handling middleware
// ---------------------------------------------------------------
app.use((err, req, res, next) => {
  // Log the full error stack for operators (do NOT expose to client)
  console.error(err);

  // Determine status code (default 500)
  const status = err.status || 500;

  // Send a generic message for 5xx errors. For 4xx we can be a bit more specific.
  const clientMessage =
    status >= 500
      ? 'Internal server error – please try again later.'
      : err.message || 'Bad request';

  res.status(status).json({ error: clientMessage });
});

// ---------------------------------------------------------------
// 7. Server bootstrap (configurable port, graceful shutdown)
// ---------------------------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`🚀 Server listening on http://localhost:${PORT}`);
});

function shutdown(signal) {
  console.log(`\nReceived ${signal} – shutting down gracefully…`);
  server.close(() => {
    console.log('✋ Server closed.');
    process.exit(0);
  });
  // Force shutdown after 10 seconds
  setTimeout(() => process.exit(1), 10_000);
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;
