## Suggested Refactored `app.js`

Below is a **complete example** that integrates the recommendations while staying close to the original functionality. Feel free to cherry‑pick only what you need.

```js
// app.js
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { celebrate, Joi, Segments, errors: celebrateErrors } = require('celebrate');
const pino = require('pino');
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });

/* ---------- Configuration validation ---------- */
const requiredEnv = ['PORT', 'CORS_ORIGIN'];
requiredEnv.forEach(v => {
  if (!process.env[v]) {
    logger.error(`Missing required environment variable: ${v}`);
    process.exit(1);
  }
});

const PORT = parseInt(process.env.PORT, 10) || 3000;
const corsOrigins = process.env.CORS_ORIGIN.split(',').map(o => o.trim());

/* ---------- App setup ---------- */
const app = express();

// Security & middleware stack
app.use(helmet());
app.use(
  cors({
    origin: corsOrigins,
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per window
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// Body parsing with size limit (useful when you add POST/PUT later)
app.use(express.json({ limit: '100kb' }));

// Helper for async route handlers
const asyncHandler = fn => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/* ---------- Routes ---------- */

// Health check – no validation needed
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users list – demonstrate query‑parameter validation
app.get(
  '/users',
  celebrate({
    [Segments.QUERY]: Joi.object({
      limit: Joi.number().integer().min(1).max(100).default(10),
      page: Joi.number().integer().min(1).default(1),
    }),
  }),
  asyncHandler(async (req, res) => {
    const { limit, page } = req.query;

    // In a real app, fetch from DB with pagination.
    // Here we mock static data.
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Very naive pagination just for illustration
    const start = (page - 1) * limit;
    const paged = allUsers.slice(start, start + limit);

    res.json(paged);
  })
);

/* ---------- 404 & Celebrate error handling ---------- */
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

app.use(celebrateErrors());

/* ---------- Central error handler ---------- */
app.use((err, req, res, next) => {
  // Log with request context if possible
  logger.error({ err, method: req.method, url: req.originalUrl }, 'Request error');

  const status = err.status || 500;
  const payload =
    process.env.NODE_ENV === 'production'
      ? { error: 'Internal Server Error' }
      : { error: err.message, stack: err.stack };

  res.status(status).json(payload);
});

/* ---------- Server start & graceful shutdown ---------- */
const server = app.listen(PORT, () => {
  logger.info(`Server listening on port ${PORT}`);
});

function gracefulShutdown(signal) {
  logger.info(`${signal} received – shutting down gracefully...`);
  server.close(err => {
    if (err) {
      logger.error('Error during server close:', err);
      process.exit(1);
    }
    logger.info('Server closed. Exiting.');
    process.exit(0);
  });
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

process.on('uncaughtException', err => {
  logger.fatal('Uncaught Exception:', err);
  process.exit(1);
});
process.on('unhandledRejection', reason => {
  logger.fatal('Unhandled Rejection:', reason);
  process.exit(1);
});

module.exports = app; // retained for testing
```

