```js
// app.js – Hardened version
'use strict';                               // Enforce strict mode

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');           // Simple request logger
const { body, param, query, validationResult } = require('express-validator');

const app = express();

/* -------------------------------------------------
   1️⃣ Core security middle‑wares
   ------------------------------------------------- */
// Secure HTTP headers
app.use(helmet());

// Basic request logging (replace with pino/winston for production)
app.use(morgan('combined'));

// CORS – adjust the whitelist to your needs
const allowedOrigins = process.env.CORS_ORIGINS?.split(',') || [];
app.use(
  cors({
    origin: (origin, callback) => {
      // Allow non‑browser requests (like health checks) with no origin
      if (!origin) return callback(null, true);
      if (allowedOrigins.length === 0 || allowedOrigins.includes(origin)) {
        return callback(null, true);
      }
      return callback(new Error('Not allowed by CORS'));
    },
    optionsSuccessStatus: 204,
  })
);

// Rate limiting – 100 requests per 15‑min window per IP (tune as needed)
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use('/api/', apiLimiter); // apply to routes under /api (or all routes)

/* -------------------------------------------------
   2️⃣ Body parsing (only JSON is needed for now)
   ------------------------------------------------- */
app.use(express.json());

/* -------------------------------------------------
   3️⃣ Helper – async wrapper to catch Promise rejections
   ------------------------------------------------- */
const asyncWrap = fn => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/* -------------------------------------------------
   4️⃣ Routes
   ------------------------------------------------- */
app.get(
  '/health',
  asyncWrap(async (req, res) => {
    // No user‑input is processed here, but we still wrap it for consistency.
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  })
);

/**
 * Example: GET /users?limit=10
 * Shows how to add validation for query parameters.
 */
app.get(
  '/users',
  // ---- Validation chain -------------------------------------------------
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt()
      .withMessage('limit must be an integer between 1 and 100'),
  ],
  // ---- Handler -----------------------------------------------------------
  asyncWrap(async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // Return 400 with a clean error payload – no stack trace.
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = req.query.limit ?? 100; // default fallback
    // In a real world app you would fetch from DB and apply the limit.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ].slice(0, limit);

    res.json(users);
  })
);

/* -------------------------------------------------
   5️⃣ Centralised error handling
   ------------------------------------------------- */
app.use((err, req, res, next) => {
  // Log the error (you could replace console.error with a proper logger)
  console.error(err);

  // Do not leak internal details in production
  const isProd = process.env.NODE_ENV === 'production';
  const status = err.status || 500;
  const response = {
    message: isProd ? 'Internal Server Error' : err.message,
    // Optionally include stack in non‑prod for debugging
    ...(isProd ? {} : { stack: err.stack }),
  };
  res.status(status).json(response);
});

/* -------------------------------------------------
   6️⃣ Server start – use env var for port, graceful shutdown
   ------------------------------------------------- */
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

/* Graceful shutdown (helps during container restarts, CI, etc.) */
function shutdown(signal) {
  console.log(`Received ${signal}. Closing server...`);
  server.close(() => {
    console.log('HTTP server closed.');
    process.exit(0);
  });
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

/* Catch unhandled promise rejections */
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production you might want to terminate the process
});

module.exports = app;
```

