}));

// 2️⃣ Generic error handler (must be after all routes)
app.use((err, req, res, next) => {
  // Log the error (use a real logger in prod)
  console.error(err);

  // Do not leak internal details – send generic message
  const status = err.status || 500;
  const message = status === 500 ? 'Internal Server Error' : err.message;

  res.status(status).json({
    error: message,
    // optional: include a request‑id for tracing
    requestId: req.id || undefined,
  });
});
