// Load environment variables (optional, for local dev)
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// ---------- Middleware ----------
app.use(helmet());                     // Security headers
app.use(express.json());               // Parse JSON bodies
app.use(express.urlencoded({ extended: false }));

// CORS whitelist (adjust to your domain)
const corsOptions = {
  origin: (origin, cb) => {
    const whitelist = ['https://myapp.example.com']; // <‑‑ edit
    if (!origin || whitelist.includes(origin)) cb(null, true);
    else cb(new Error('Not allowed by CORS'));
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
};
app.use(cors(corsOptions));

// Rate limiting (example: 100 req/min per IP globally)
const limiter = rateLimit({
  windowMs: 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---------- Helper: async wrapper ----------
const asyncHandler = fn => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get(
  '/users',
  asyncHandler(async (req, res) => {
    // In a real app this would hit a DB
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  })
);

// Example of a POST route with validation (for future expansion)
app.post(
  '/users',
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters'),
    body('email')
      .normalizeEmail()
      .isEmail()
      .withMessage('A valid email address is required'),
  ],
  asyncHandler(async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      const err = new Error('Validation failed');
      err.status = 400;
      err.details = errors.array();
      throw err;
    }

    // Simulate DB insert
    const { name, email } = req.body;
    const newUser = { id: Date.now(), name, email };
    // Respond with created entity
    res.status(201).json(newUser);
  })
);

// ---------- Central Error Handler ----------
app.use((err, req, res, next) => {
  // Log – replace with a proper logger in production
  console.error(err);

  const status = err.status || 500;
  const response = {
    error: status === 500 ? 'Internal Server Error' : err.message,
  };

  // If you attached extra details (e.g., validation), expose them conditionally
  if (process.env.NODE_ENV !== 'production' && err.details) {
    response.details = err.details;
  }

  res.status(status).json(response);
});

// ---------- Server startup ----------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
function shutdown() {
  console.log('Received shutdown signal – closing server...');
  server.close(() => {
    console.log('Server closed. Exiting process.');
    process.exit(0);
  });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

// Catch uncaught exceptions / rejections
process.on('uncaughtException', err => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;
```

