// ----------------------------------------------------
require('dotenv').config();               // ← load env vars from .env (git‑ignore this!)
const express = require('express');
const helmet = require('helmet');          // security headers
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');          // HTTP request logging
const { celebrate, Joi, errors, Segments } = require('celebrate'); // input validation
const createError = require('http-errors'); // standardized errors

const app = express();

// ---------- 1. Global middleware ----------
app.use(helmet());                         // sets dozens of headers
app.use(express.json({ limit: '5kb' }));   // body parser with size limit
app.use(express.urlencoded({ extended: false }));
app.set('trust proxy', 1);                 // needed when behind a proxy

// Request logger (output to console; replace with winston/bunyan for prod)
app.use(morgan('combined'));

// ---------- 2. CORS ----------
app.use(
  cors({
    origin: process.env.ALLOWED_ORIGINS?.split(',') || [], // e.g. "https://myapp.com"
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);

// ---------- 3. Rate limiting ----------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json({ error: 'Too many requests – try again later.' });
  },
});
app.use('/users', apiLimiter); // apply only where needed (or app.use(apiLimiter) for all)

// ---------- 4. Routes ----------
