  }),
  (req, res, next) => {
    try {
      const { limit, offset } = req.query;
      // In a real app you'd fetch from DB with the validated parameters.
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ].slice(offset, offset + limit);
      res.json(users);
    } catch (err) {
      next(err); // forward to error handler
    }
  }
);

// ---------- 5. Celebrate (Joi) error handling ----------
app.use(errors()); // formats validation errors nicely

// ---------- 6. Central error handler ----------
app.use((err, req, res, next) => {
  // Normalize to an HTTP error if needed
  const error = createError(err);
  const status = error.status || 500;

  // Log the error (avoid leaking stack in prod)
  console.error(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl} → ${status}`, err);

