  // Running directly (node app.js) – start the HTTP server.
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

// Export the app for testing (no side‑effects)
module.exports = app;
