## 3️⃣ Refactored Example (`app.js`)

Below is a **drop‑in replacement** that adds the above hardening while keeping the original functionality.  
If you prefer to keep `app.js` as a pure Express router, you can move the server bootstrap to a separate `server.js` – the principle is the same.

```js
/**
 * app.js – Express application with security‑hardening middleware,
 *           centralised error handling and input validation scaffolding.
 */

require('dotenv').config();                // <-- Load .env (PORT, etc.)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { celebrate, Joi, errors, Segments } = require('celebrate'); // validation lib
// const logger = require('./logger'); // optional winston/pino logger

const app = express();

/* -------------------------------------------------------------
 * 1️⃣ Global Middleware – security, parsing, logging
 * -----------------------------------------------------------*/
app.use(helmet());                         // security headers
app.use(express.json({ limit: '10kb' }));  // body parser + size limit
app.use(morgan('combined'));               // HTTP request logging

// ---- CORS (customise whitelist as needed) ----
const allowedOrigins = process.env.CORS_ORIGINS?.split(',') || ['http://localhost:3000'];
app.use(
  cors({
    origin: (origin, callback) => {
      // allow non‑browser requests like curl/postman (origin === undefined)
      if (!origin || allowedOrigins.includes(origin)) {
        callback(null, true);
      } else {
        callback(new Error('Not allowed by CORS'));
      }
    },
    credentials: true,
  })
);

// ---- Rate limiting (adjust windows / limits for your workload) ----
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/users', apiLimiter); // apply only to endpoints that can be abused

/* -------------------------------------------------------------
 * 2️⃣ Routes – with optional validation (example shown for /users)
 * -----------------------------------------------------------*/

// Health‑check – no validation needed
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * - Example of request‑query validation (e.g., pagination) using celebrate/Joi.
 * - If you later add POST/PUT routes, follow the same pattern.
 */
app.get(
  '/users',
  celebrate({
    [Segments.QUERY]: Joi.object({
      limit: Joi.number().integer().min(1).max(100).default(10),
      offset: Joi.number().integer().min(0).default(0),
    }),
  }),
  (req, res, next) => {
    try {
      // In a real app this would be a DB call; keep static data for demo.
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply simple pagination based on validated query params
      const { limit, offset } = req.query;
      const paged = users.slice(offset, offset + limit);

      res.json(paged);
    } catch (err) {
      // Pass any unexpected error to the error handler
      next(err);
    }
  }
);

/* -------------------------------------------------------------
 * 3️⃣ Celebrate validation errors – turn them into proper JSON responses
 * -----------------------------------------------------------*/
app.use(errors());

/* -------------------------------------------------------------
 * 4️⃣ Centralised error‑handling middleware
 * -----------------------------------------------------------*/
app.use((err, req, res, _next) => {
  // Log the error (replace console.log with winston/pino in prod)
  console.error(err);

  // Do NOT leak stack traces or internal details in production
  const isProd = process.env.NODE_ENV === 'production';
  const status = err.status || 500;

  const payload = {
    error: {
      message: err.message || 'Internal Server Error',
    },
  };

  if (!isProd && err.stack) {
    payload.error.stack = err.stack;
  }

  res.status(status).json(payload);
});

/* -------------------------------------------------------------
 * 5️⃣ Export the app (useful for testing) & optional server start
 * -----------------------------------------------------------*/
module.exports = app;

// If this file is executed directly (`node app.js`) start listening.
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`🚀 Server listening on port ${PORT}`);
  });
}

/* -------------------------------------------------------------
 * 6️⃣ Process‑level safety (unhandled rejections, uncaught exceptions)
 * -----------------------------------------------------------*/
process.on('unhandledRejection', (reason) => {
  console.error('❌ Unhandled Promise Rejection:', reason);
  // Optionally attempt graceful shutdown
});

process.on('uncaughtException', (err) => {
  console.error('❌ Uncaught Exception:', err);
  // In most cases you should exit – the process may be in an undefined state.
  process.exit(1);
});

/* -------------------------------------------------------------
 * 7️⃣ Graceful shutdown (SIGTERM / SIGINT) – useful in Docker / k8s
 * -----------------------------------------------------------*/
function shutdown() {
  console.log('🛑 Received kill signal, shutting down gracefully...');
  // If you have DB connections, close them here.
  process.exit(0);
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
```

